import unittest
from ui import STATUS_LABEL, export_button

class UiTests(unittest.TestCase):
    def test_busy_button(self):
        self.assertIn('disabled', export_button(busy=True))
    def test_ready_button(self):
        self.assertNotIn('disabled', export_button(busy=False))
    def test_status_label(self):
        self.assertEqual('Save', STATUS_LABEL)
